(()=>{
 const button=document.createElement('button');button.textContent='🔔 Notificações';document.querySelector('aside nav').append(button);
 const dialog=document.createElement('dialog');dialog.id='notifications-dialog';document.body.append(dialog);
 let items=[],unread=0,filter='all',epoch=0,sequence=0,timer=null;const watermarks=new Map();
 const compare=(a,b)=>BigInt(a||0)>BigInt(b||0);
 function badge(){button.textContent='🔔 Notificações'+(unread?' · '+unread:'');button.classList.toggle('has-unread',unread>0);supportButton.textContent='☏ Call Adm'+(unread?' · '+unread+' nova(s)':'');supportButton.classList.toggle('has-unread',unread>0)}
 window.paintNotificationBadge=badge;
 function render(){if(!dialog.open)return;dialog.innerHTML=`<button class="close" aria-label="Fechar notificações">×</button><span class="eyebrow">SEU ATENDIMENTO</span><h2>Notificações</h2><p>${unread?`${unread} mensagem(ns) não lida(s) no Call Adm.`:'Você está em dia com as mensagens.'}</p><div class="notification-controls"><button data-notification-filter="all" ${filter==='all'?'aria-pressed="true"':''}>Todas</button><button data-notification-filter="unread" ${filter==='unread'?'aria-pressed="true"':''}>Não lidas</button><button id="notifications-read-all" class="text-btn" ${!unread?'disabled':''}>Marcar todas como lidas</button></div><div class="notification-list">${items.filter(row=>filter==='all'||row.unread_count>0).map(row=>`<article class="notification-item ${row.unread_count?'notification-new':''}"><span class="notification-symbol">${row.unread_count?'●':'✓'}</span><div><strong>${esc(account.admin?row.thread_name||row.sender_name:'Administração')}</strong><small>${esc(new Date(row.created_at).toLocaleString('pt-BR'))}${row.unread_count?' · '+row.unread_count+' não lida(s)':''}</small><p>${esc(row.body)}</p><button data-notification-open="${esc(row.thread_user_id)}">Abrir conversa ↗</button>${row.unread_count?`<button class="text-btn" data-notification-read="${esc(row.thread_user_id)}" data-read-id="${esc(row.id)}">Marcar conversa como lida</button>`:''}</div></article>`).join('')||'<div class="empty"><h3>Nenhuma notificação por aqui.</h3><p>Novas mensagens do Call Adm aparecerão nesta tela.</p></div>'}</div><p id="notifications-status" role="status"></p>`}
 async function load(){const seq=++sequence,version=epoch;try{const r=await fetch('/api/notifications/',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();if(seq!==sequence)return;if(version!==epoch){clearTimeout(timer);timer=setTimeout(load,300);return}items=data.items;unread=data.unread;badge();render()}catch{const status=dialog.querySelector('#notifications-status');if(status)status.textContent='Não foi possível atualizar. Suas notificações serão consultadas novamente.'}}
 async function read(thread,id,all=false){if(!all&&(!id||!/^\d+$/.test(String(id))||(!compare(id,watermarks.get(thread)))))return;if(!all)watermarks.set(thread,String(id));epoch++;for(const item of items)if(all||item.thread_user_id===thread){unread=Math.max(0,unread-item.unread_count);item.unread_count=0}badge();render();try{const r=await fetch('/api/notifications/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(all?{action:'all'}:{action:'read',thread,id:String(id)})});if(!r.ok)throw Error();load()}catch{if(!all)watermarks.delete(thread);load()}}
 window.markSupportConversationRead=(thread,id)=>read(thread,id);
 button.onclick=()=>{render();dialog.showModal();render();load()};
 dialog.onclick=event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.notificationFilter){filter=target.dataset.notificationFilter;render()}if(target.id==='notifications-read-all')read('',null,true);if(target.dataset.notificationRead)read(target.dataset.notificationRead,target.dataset.readId);if(target.dataset.notificationOpen){const thread=target.dataset.notificationOpen;dialog.close();supportTarget=account.admin?thread:account.user.id;supportRows=[];supportRowsTarget=supportTarget;openSupport()}};
 window.addEventListener('study-support-message',event=>{const data=event.detail;if(!data?.message||data.senderId===account.user.id)return;const visible=supportDialog.open&&supportTarget===data.threadUserId&&!document.hidden;if(visible){read(data.threadUserId,data.id);return}epoch++;let item=items.find(row=>row.thread_user_id===data.threadUserId);if(!item){item={thread_user_id:data.threadUserId,unread_count:0};items.unshift(item)}if(compare(data.id,item.id)){Object.assign(item,{id:String(data.id),thread_name:data.threadName||item.thread_name||data.message.sender_name,sender_name:data.message.sender_name,body:data.message.body.slice(0,180),created_at:data.message.created_at,from_admin:data.message.from_admin});item.unread_count++;unread++;items.sort((a,b)=>compare(a.id,b.id)?-1:1);items=items.slice(0,50);badge();render()}});
 window.addEventListener('study-support-connected',load);window.addEventListener('study-notifications-sync',load);
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)load()});setInterval(()=>{if(!document.hidden)load()},15000);load();
})();
